// GENERATED by crashtest. Idempotency helper, copied into your app as agent/lib/crashtest-idempotency.ts.
// It makes a tool's side effect run at most once per operation, so a replay after a crash does not repeat it:
//
//   const key = opKey(ctx, { to, orderId }); // identity fields only: never ctx.callId, never free text
//   return once(key, defaultStore(), () => sendMessage({ to, orderId, text }));
//
// First attempt: records "started", runs the side effect, records "done" with its result.
// Replay after "done": returns the stored result without running the side effect again.
// Replay after "started" (a crash, or a failure, before "done"): throws OutcomeUnknownError, whose message tells
// the model the effect may or may not have happened, so it checks before retrying. At most once wins over at least once.
// When the side effect ran but its "done" record cannot be stored (the store is down, the result is not
// JSON-serializable), the caller still gets the result and a console warning names the store failure; the record
// stays "started", so a replay gets OutcomeUnknownError.
// Results must be JSON-serializable. This file imports only node built-ins, so it can be copied anywhere.
import { createHash, randomUUID } from "node:crypto";
import { promises as fs } from "node:fs";
import { join } from "node:path";

/** Thrown when a previous attempt of the same operation started but never recorded that it finished. */
export class OutcomeUnknownError extends Error {
  readonly code = "OUTCOME_UNKNOWN";

  constructor() {
    super(
      "OUTCOME_UNKNOWN: a previous attempt of this operation started but did not finish; check whether it took effect before retrying.",
    );
    this.name = "OutcomeUnknownError";
  }
}

export type OpRecord = { state: "started" } | { state: "done"; result: unknown };

export interface Store {
  get(key: string): Promise<OpRecord | null>;
  /** Stores the record only if the key is free: resolves false when a record already exists. */
  create(key: string, rec: OpRecord): Promise<boolean>;
  /** Replaces the record. */
  put(key: string, rec: OpRecord): Promise<void>;
}

// ---------------------------------------------------------------- op-key

/** The value with the keys of every object sorted, so equal identities serialize equally. */
function canonical(value: unknown): unknown {
  if (typeof value !== "object" || value === null) return value;
  const toJson = (value as { toJSON?: unknown }).toJSON;
  if (typeof toJson === "function") return canonical(toJson.call(value));
  if (Array.isArray(value)) return value.map(canonical);
  return Object.fromEntries(
    Object.keys(value)
      .sort()
      .map((key) => [key, canonical((value as Record<string, unknown>)[key])]),
  );
}

/** Hex sha256 over the session, the turn, the tool name and the identity fields of the operation. */
export function opKey(
  ctx: { session: { id: string; turn: { id: string } }; toolName: string },
  identity: Record<string, unknown>,
): string {
  const parts = [ctx.session.id, ctx.session.turn.id, ctx.toolName, canonical(identity)];
  return createHash("sha256").update(JSON.stringify(parts)).digest("hex");
}

// ---------------------------------------------------------------- stores

/** A record that is there but is not a finished one (cut off by a kill, unreadable, unknown) counts as started. */
function parseRecord(text: unknown): OpRecord {
  if (typeof text === "string") {
    try {
      const value = JSON.parse(text) as { state?: unknown; result?: unknown } | null;
      if (value?.state === "done") return { state: "done", result: value.result };
    } catch {
      // Falls through: an unparseable record is an attempt that did not finish.
    }
  }
  return { state: "started" };
}

function errorCode(error: unknown): unknown {
  return typeof error === "object" && error !== null ? (error as { code?: unknown }).code : undefined;
}

// An op-key is lowercase hex. Keys become file names, so anything else that could leave the directory, or
// collide on a case-insensitive file system, is rejected.
const FILE_KEY = /^[a-z0-9_-]{1,128}$/;

function recordFile(dir: string, key: string): string {
  if (!FILE_KEY.test(key)) {
    throw new Error('fileStore: key must be 1 to 128 characters from a-z, 0-9, "-" and "_" (build it with opKey)');
  }
  return join(dir, `${key}.json`);
}

/** One JSON file per key in `dir` (default: CRASHTEST_IDEMPOTENCY_DIR, else ./.crashtest-idempotency). */
export function fileStore(dir: string = process.env["CRASHTEST_IDEMPOTENCY_DIR"] || ".crashtest-idempotency"): Store {
  return {
    async get(key) {
      const file = recordFile(dir, key);
      let text: string;
      try {
        text = await fs.readFile(file, "utf8");
      } catch (error) {
        if (errorCode(error) === "ENOENT") return null;
        // The record is there but cannot be read: an attempt that did not finish, as far as anyone can tell.
        return { state: "started" };
      }
      return parseRecord(text);
    },

    async create(key, rec) {
      const file = recordFile(dir, key);
      await fs.mkdir(dir, { recursive: true });
      try {
        await fs.writeFile(file, JSON.stringify(rec), { flag: "wx" });
        return true;
      } catch (error) {
        if (errorCode(error) === "EEXIST") return false;
        throw error;
      }
    },

    async put(key, rec) {
      const file = recordFile(dir, key);
      const text = JSON.stringify(rec);
      await fs.mkdir(dir, { recursive: true });
      // Written next to the record and renamed over it, so a reader never sees half a "done" record.
      const temp = `${file}.${process.pid}.${randomUUID()}.tmp`;
      try {
        await fs.writeFile(temp, text);
        await fs.rename(temp, file);
      } catch (error) {
        await fs.rm(temp, { force: true }).catch(() => {});
        throw error;
      }
    },
  };
}

/** Sends one Redis command to an Upstash REST endpoint and returns its result. The token is never put in an error. */
async function redisCommand(url: string, token: string, command: string[]): Promise<unknown> {
  const name = command[0];
  const response = await fetch(url, {
    method: "POST",
    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
    body: JSON.stringify(command),
  });
  let payload: unknown = null;
  try {
    payload = JSON.parse(await response.text());
  } catch {
    // Reported below.
  }
  const body = typeof payload === "object" && payload !== null ? (payload as { result?: unknown; error?: unknown }) : null;
  const detail = typeof body?.error === "string" ? `: ${body.error}` : "";
  if (!response.ok) throw new Error(`redisRestStore: ${name} failed with HTTP ${response.status}${detail}`);
  if (body === null) throw new Error(`redisRestStore: ${name} returned a response that is not a JSON object`);
  if (body.error !== undefined) throw new Error(`redisRestStore: ${name} failed${detail}`);
  return body.result;
}

/** Upstash Redis over REST (UPSTASH_REDIS_REST_URL and UPSTASH_REDIS_REST_TOKEN unless given). Throws if either is missing. */
export function redisRestStore(o: { url?: string; token?: string } = {}): Store {
  const url = o.url || process.env["UPSTASH_REDIS_REST_URL"];
  const token = o.token || process.env["UPSTASH_REDIS_REST_TOKEN"];
  if (!url || !token) {
    const missing = [!url && "UPSTASH_REDIS_REST_URL", !token && "UPSTASH_REDIS_REST_TOKEN"].filter(Boolean);
    throw new Error(`redisRestStore: missing ${missing.join(" and ")}; set it in the environment or pass it as an option`);
  }
  const expectOk = (name: string, result: unknown): void => {
    if (result !== "OK") throw new Error(`redisRestStore: ${name} returned an unexpected result`);
  };

  return {
    async get(key) {
      const result = await redisCommand(url, token, ["GET", key]);
      return result === null ? null : parseRecord(result);
    },

    async create(key, rec) {
      const result = await redisCommand(url, token, ["SET", key, JSON.stringify(rec), "NX"]);
      if (result === null) return false;
      expectOk("SET NX", result);
      return true;
    },

    async put(key, rec) {
      expectOk("SET", await redisCommand(url, token, ["SET", key, JSON.stringify(rec)]));
    },
  };
}

/** Redis when both Upstash variables are set, else the file store. */
export function defaultStore(): Store {
  return process.env["UPSTASH_REDIS_REST_URL"] && process.env["UPSTASH_REDIS_REST_TOKEN"] ? redisRestStore() : fileStore();
}

// ---------------------------------------------------------------- once

function replay<T>(record: OpRecord): T {
  if (record.state === "done") return record.result as T;
  throw new OutcomeUnknownError();
}

/** What a warning may say about a store failure: the error's own text, never a value it was handed. */
function describeFailure(error: unknown): string {
  return error instanceof Error ? `${error.name}: ${error.message}` : "a value that is not an Error was thrown";
}

/**
 * Runs `fn` at most once for `key`. See the header for what a repeat gets. If `fn` throws, the record stays "started".
 * If `fn` succeeded but its result cannot be stored, the result is returned anyway (the effect happened) and the
 * record stays "started".
 */
export async function once<T>(key: string, store: Store, fn: () => Promise<T>): Promise<T> {
  const existing = await store.get(key);
  if (existing !== null) return replay<T>(existing);

  if (!(await store.create(key, { state: "started" }))) {
    // Another attempt took the key between our read and our create: apply the same rules to what it wrote.
    // A record that is gone again is treated like a started one.
    const winner = await store.get(key);
    if (winner === null) throw new OutcomeUnknownError();
    return replay<T>(winner);
  }

  const result = await fn();
  try {
    await store.put(key, { state: "done", result });
  } catch (error) {
    // Failing here would tell the model the operation failed although it happened.
    console.warn(
      `crashtest-idempotency: the operation ran, but its result could not be stored (${describeFailure(error)}); a repeat of it will get OUTCOME_UNKNOWN.`,
    );
  }
  return result;
}
